//! The public twin in office and mail formats reconciles to the same answer
//! (`testdata/golden/vantara-twin-escritorio` and `vantara-twin-msg-7z`, generated by
//! `testdata/synth/formatos_escritorio.py`), and files of these formats that cannot take part
//! in a run leave a warning and change nothing.

use std::path::{Path, PathBuf};

use dm_eval::{find_golden_dirs, find_twin_dir, load, run_golden};
use dm_recon::{run_dir, EngineConfig};

fn twin() -> PathBuf {
    find_twin_dir(Path::new(
        &std::env::var("CARGO_MANIFEST_DIR")
            .expect("cargo define CARGO_MANIFEST_DIR ao rodar os testes"),
    ))
    .unwrap_or_else(|| panic!("testdata/golden/vantara-twin não encontrado"))
}

fn read(path: &Path) -> Vec<u8> {
    std::fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn scores_like_the_twin(variant: &Path) -> Vec<String> {
    let run = run_golden(variant, &EngineConfig::default(), 10).unwrap_or_else(|e| panic!("{e}"));
    assert!(
        run.scorecard.perfect(),
        "{}:\n{}",
        variant.display(),
        run.scorecard.report()
    );
    assert!(run.identical, "dez execuções deram resultados diferentes");
    assert_eq!(
        run.scorecard.summary(),
        "18/18 linhas, 17/17 títulos, 23/23 achados"
    );
    assert_eq!(
        (run.scorecard.totals.ok, run.scorecard.totals.total),
        (11, 11)
    );
    // The answer key is the twin's with only the case name and file names changed.
    let twin_expected = load(&twin().join("expected.yaml")).unwrap_or_else(|e| panic!("{e}"));
    let mut expected = load(&variant.join("expected.yaml")).unwrap_or_else(|e| panic!("{e}"));
    expected.sources.clone_from(&twin_expected.sources);
    expected.case.clone_from(&twin_expected.case);
    assert_eq!(expected.to_json(), twin_expected.to_json());
    assert!(find_golden_dirs(Path::new(
        &std::env::var("CARGO_MANIFEST_DIR")
            .expect("cargo define CARGO_MANIFEST_DIR ao rodar os testes")
    ))
    .contains(&variant.to_path_buf()));
    run_dir(variant, &EngineConfig::default())
        .unwrap_or_else(|e| panic!("{e}"))
        .dataset
        .warnings
}

#[test]
fn odt_json_html_and_docx_score_100() {
    let variant = twin().with_file_name("vantara-twin-escritorio");
    let warnings = scores_like_the_twin(&variant);
    assert!(warnings.is_empty(), "{warnings:?}");
    let ds = run_dir(&variant, &EngineConfig::default())
        .unwrap_or_else(|e| panic!("{e}"))
        .dataset;
    let source = |key: &str| ds.sources.get(key).map(String::as_str);
    assert_eq!(
        source("protheus"),
        Some("01_contas_a_receber_protheus_jul2026.odt")
    );
    assert_eq!(
        source("omie"),
        Some("02_titulos_unidade_norte_omie_jul2026.json")
    );
    assert_eq!(source("bank"), Some("03_extrato_bancario_jul2026.html"));
    assert_eq!(
        source("ap_inbox"),
        Some("04_caixa_de_entrada_contas_a_pagar.docx")
    );
}

#[test]
fn ledgers_in_a_7z_and_statement_in_an_outlook_message_score_100() {
    let variant = twin().with_file_name("vantara-twin-msg-7z");
    let warnings = scores_like_the_twin(&variant);
    // The banker's e-mail is an inbox too; the exported one has more messages and wins.
    assert_eq!(
        warnings,
        vec!["03_extrato_bancario_jul2026.msg: segunda caixa de entrada; só 04_caixa_de_entrada_contas_a_pagar.txt entra nesta conciliação".to_string()]
    );
    assert_eq!(
        read(&variant.join("04_caixa_de_entrada_contas_a_pagar.txt")),
        read(&twin().join("04_caixa_de_entrada_contas_a_pagar.txt"))
    );
    let ds = run_dir(&variant, &EngineConfig::default())
        .unwrap_or_else(|e| panic!("{e}"))
        .dataset;
    assert_eq!(
        ds.sources.get("bank").map(String::as_str),
        Some("03_extrato_bancario_jul2026.msg/extrato_conta_jul2026.csv")
    );
    assert_eq!(
        ds.sources.get("protheus").map(String::as_str),
        Some("01_carteira_jul2026.7z/carteiras/01_contas_a_receber_protheus_jul2026.xml")
    );
}

/// Office and mail files that hold nothing to reconcile, next to the twin, change nothing
/// and each one is named in the warnings.
#[test]
fn unusable_office_files_are_reported_and_change_nothing() {
    let dir = tempfile::tempdir().unwrap_or_else(|e| panic!("{e}"));
    for name in [
        "01_contas_a_receber_protheus_jul2026.csv",
        "02_titulos_unidade_norte_omie_jul2026.csv",
        "03_extrato_bancario_jul2026.csv",
        "04_caixa_de_entrada_contas_a_pagar.txt",
        "expected.yaml",
    ] {
        std::fs::copy(twin().join(name), dir.path().join(name)).unwrap_or_else(|e| panic!("{e}"));
    }
    // A letter in Word: paragraphs only, no table, no e-mail.
    let mut docx = std::io::Cursor::new(Vec::new());
    {
        use std::io::Write;
        let mut w = zip::ZipWriter::new(&mut docx);
        let opts = zip::write::SimpleFileOptions::default();
        for (name, body) in [
            ("[Content_Types].xml", "<Types/>"),
            (
                "word/document.xml",
                "<w:document xmlns:w=\"w\"><w:body><w:p><w:r><w:t>Prezados, segue a política de cobrança.</w:t></w:r></w:p></w:body></w:document>",
            ),
        ] {
            w.start_file(name, opts).unwrap_or_else(|e| panic!("{e}"));
            w.write_all(body.as_bytes())
                .unwrap_or_else(|e| panic!("{e}"));
        }
        w.finish().unwrap_or_else(|e| panic!("{e}"));
    }
    std::fs::write(dir.path().join("05_politica.docx"), docx.into_inner())
        .unwrap_or_else(|e| panic!("{e}"));
    std::fs::write(
        dir.path().join("06_config.xml"),
        b"<config><a>1</a></config>",
    )
    .unwrap_or_else(|e| panic!("{e}"));
    std::fs::write(dir.path().join("07_vazio.json"), b"[]").unwrap_or_else(|e| panic!("{e}"));
    std::fs::write(
        dir.path().join("08_quebrado.7z"),
        b"7z\xBC\xAF\x27\x1C\x00\x04lixo",
    )
    .unwrap_or_else(|e| panic!("{e}"));
    std::fs::write(
        dir.path().join("09_pagina.html"),
        b"<html><body><p>Sem tabela nenhuma.</p></body></html>",
    )
    .unwrap_or_else(|e| panic!("{e}"));
    let run = run_golden(dir.path(), &EngineConfig::default(), 1).unwrap_or_else(|e| panic!("{e}"));
    assert!(run.scorecard.perfect(), "{}", run.scorecard.report());
    let ds = run_dir(dir.path(), &EngineConfig::default())
        .unwrap_or_else(|e| panic!("{e}"))
        .dataset;
    let all = ds.warnings.join("\n");
    for (file, reason) in [
        (
            "05_politica.docx",
            "lido (documento Word (DOCX)), mas nada foi reconhecido",
        ),
        ("06_config.xml", "XML sem registros repetidos"),
        ("07_vazio.json", "JSON sem lista de registros"),
        ("08_quebrado.7z", "arquivo 7z ilegível"),
        (
            "09_pagina.html",
            "lido (página HTML), mas nada foi reconhecido",
        ),
    ] {
        assert!(
            ds.warnings
                .iter()
                .any(|w| w.starts_with(&format!("{file}: ")) && w.contains(reason)),
            "sem aviso de {file} ({reason}):\n{all}"
        );
    }
}
